 static void capacity(){check(CombatNpcDamageQueue.pending()==0,"capacity fixture begins with no live actor work");var event=new CombatNpcDamageQueue.Event(0,0,ClassicWorldMonsterPopulation.ContributorKind.PLAYER,1,1,5,1,"source","account","name");var queues=new java.util.ArrayList<CombatNpcDamageQueue.Queue>();for(int q=0;q<16;q++){var queue=new CombatNpcDamageQueue.Queue();queues.add(queue);for(int i=0;i<4096;i++)if(!queue.offer(event))throw new AssertionError("source default target/global admission failed");check(queue.pending()==4096&&!queue.offer(event),"source default per-target4096 bound");}var blocked=new CombatNpcDamageQueue.Queue();check(CombatNpcDamageQueue.pending()==65536&&!blocked.offer(event),"source default global65536 bound");for(var q:queues)q.clear(true);check(CombatNpcDamageQueue.pending()==0,"bulk disposal releases every global admission exactly once");var queue=new CombatNpcDamageQueue.Queue();check(queue.offer(event)&&queue.start()&&queue.claim()==event,"one FIFO consumer owns exact accepted event");queue.clear(true);check(queue.pending()==1&&!queue.offer(event),"terminal close drops waiting events but retains active receipt");queue.complete(event);check(queue.claim()==null&&queue.pending()==0&&CombatNpcDamageQueue.pending()==0,"active receipt retires exactly once after close");}
