 static void rejectedDispatch(ClientSession pc,ClientSession peer,GameHub hub,ClassicWorldMonsterPopulation pop,boolean retryClock)throws Exception{
  var savedClock=(ScheduledExecutorService)get(hub,"battleClock");var retry=retryClock?Executors.newSingleThreadScheduledExecutor():null;if(retry!=null)set(hub,"battleClock",retry);try{
  var entered=new java.util.concurrent.CountDownLatch(CombatNpcDamageQueue.WORKERS);var release=new java.util.concurrent.CountDownLatch(1);var done=new java.util.concurrent.CountDownLatch(CombatNpcDamageQueue.DISPATCH_CAPACITY+CombatNpcDamageQueue.WORKERS);Runnable occupy=()->{entered.countDown();try{if(!release.await(5,java.util.concurrent.TimeUnit.SECONDS))throw new AssertionError("commit saturation fixture timeout");}catch(InterruptedException e){Thread.currentThread().interrupt();}finally{done.countDown();}};
  for(int i=0;i<CombatNpcDamageQueue.WORKERS;i++)if(!CombatNpcDamageQueue.submit(occupy))throw new AssertionError("commit worker rejected");check(entered.await(3,java.util.concurrent.TimeUnit.SECONDS),"configured real commit workers occupied");var a=spawn(pop,4130);long id=a.objectId();var t=timed(pop,id);try{for(int n=0;n<CombatNpcDamageQueue.DISPATCH_CAPACITY;n++)if(!CombatNpcDamageQueue.submit(occupy))throw new AssertionError("bounded dispatch queue capacity drift");produce(pc,companionDamage(pc,BattleCompanion.Kind.SUMMON),a);long now=next(t),rejected=CombatNpcDamageQueue.rejections();try(var scope=CombatPoisonLifecycle.open()){dispatch(pc,CombatMonsterCurseLifecycle.pollDamageWorld(hub,4,-1,now,3000,5,pc,scope),now,scope);}check(CombatNpcDamageQueue.rejections()>=rejected+1&&hp(pop,id)==50000,"rejected executor never runs HP on submitting timer thread");castMonster(peer,a,9);check(poisonLease(t)==null&&CombatNpcDamageQueue.pending()==1,"cure retains accepted event awaiting dispatch retry");}finally{release.countDown();check(done.await(5,java.util.concurrent.TimeUnit.SECONDS),"all bounded dispatch filler tasks drained");}
  if(retryClock)drain(hub);else tick(pc,System.nanoTime());check(hp(pop,id)==49995&&CombatNpcDamageQueue.pending()==0,"next native clock retries accepted input after cure without re-admission");pop.damage(4,id,50000);
  }finally{if(retry!=null){retry.shutdownNow();check(retry.awaitTermination(2,TimeUnit.SECONDS),"consumer retry handoff executor stopped");set(hub,"battleClock",savedClock);}}
 }
